/**
 * The towns the agent names places by: what the stream tools' world-query names places by ("42.4N, 32.2E inside a
 * building (Holtburg)"), and what a walk_to target may name a place by ("Holtburg lifestone"). Per era, from that
 * era's own data (BUG.ac1999-map-eor-art follow-up): an era whose client has map notes uses them (gmMapUI
 * s_rgLocations, EraClientRules.mapPanel.notes: end of retail's 53, ClassicACE CustomDM's with Sanamar called
 * "Other"); the 1999 client has none, so 1999 uses its world's towns (towns1999.ts, generated by
 * tools/build-agent-towns.ts from the 1999 map marker table and the 1999 cell.dat). main.ts sets the era once per
 * page load (setAgentTownsEra); until then, and outside the page (the stream tools), end of retail's.
 */
import { MAP_NOTE_LOCATIONS, type MapNoteLocation } from '../ui/HudTooltips.js';
import { MAP_MARKER_AREA, PLACE_MARKER_BIAS, PLACE_MARKER_FLIP, PLACE_MARKER_SCALE, PLACE_MARKER_STEP, type MapCoords } from '../ui/MapMarkers.js';
import { eraClientRules } from '../era/EraFeatures.js';
import type { EraProfile } from '../era/EraProfiles.js';
import { AC1999_TOWN_ROWS } from './towns1999.js';

export interface AgentTown { name: string; coords: MapCoords }

/** Map notes as towns: each note's rect centre turned back into map coordinates (placeMarkerOnMap inverted). */
export function townsOfNotes(notes: readonly MapNoteLocation[]): readonly AgentTown[] {
  return notes.map((l) => {
    const a = MAP_MARKER_AREA;
    const px = l.x + l.width / 2, py = l.y + l.height / 2;
    const ew = ((px - a.x0) / ((a.x1 - a.x0 + 1) * -PLACE_MARKER_STEP) - PLACE_MARKER_BIAS) / PLACE_MARKER_SCALE;
    const ns = (PLACE_MARKER_FLIP - (py - a.y0) / ((a.y1 - a.y0 + 1) * -PLACE_MARKER_STEP) - PLACE_MARKER_BIAS) / PLACE_MARKER_SCALE;
    return { name: l.name, coords: { ew, ns } };
  });
}

/** End of retail's towns: the end-of-retail map notes. */
export const MAP_TOWNS: readonly AgentTown[] = townsOfNotes(MAP_NOTE_LOCATIONS);

/** The 1999 world's towns and outposts (towns1999.ts). */
export const AC1999_TOWNS: readonly AgentTown[] = AC1999_TOWN_ROWS.map(([name, ns, ew]) => ({ name, coords: { ns, ew } }));

/** Towns for an era with no map notes, by era id: generated from that era's world data. */
const WORLD_TOWNS: Readonly<Record<string, readonly AgentTown[]>> = { 'ac1999-retail': AC1999_TOWNS };

const notesTowns = new WeakMap<object, readonly AgentTown[]>();
/** Era `p`'s towns: its client's map notes, else its world's table (none known: no towns). */
export function eraTowns(p: EraProfile | null | undefined): readonly AgentTown[] {
  const notes = eraClientRules(p).mapPanel.notes;
  if (notes === MAP_NOTE_LOCATIONS) return MAP_TOWNS;
  if (notes.length === 0) return (p && WORLD_TOWNS[p.id]) ?? [];
  let t = notesTowns.get(notes);
  if (!t) notesTowns.set(notes, (t = townsOfNotes(notes)));
  return t;
}

let activeTowns: readonly AgentTown[] = MAP_TOWNS;
/** The page's era (main.ts, once per load): nearestTownOf / townInName use its towns. */
export function setAgentTownsEra(p: EraProfile | null | undefined): void {
  activeTowns = eraTowns(p);
}
/** The towns in use. */
export function agentTowns(): readonly AgentTown[] {
  return activeTowns;
}

/** Within this many map units (0.1 = 24 m) of a town's point a place is "in" it. */
export const IN_TOWN_UNITS = 3;

/** The nearest town on the map within 15 map units: its name, the distance, and the text ("Holtburg" within 3, else "5 SW of Holtburg"). */
export function nearestTownOf(c: MapCoords, towns: readonly AgentTown[] = activeTowns): { name: string; distance: number; text: string } | undefined {
  let best: { name: string; d: number; dn: number; de: number } | undefined;
  for (const t of towns) {
    const dn = c.ns - t.coords.ns, de = c.ew - t.coords.ew;
    const d = Math.hypot(dn, de);
    if (!best || d < best.d) best = { name: t.name, d, dn, de };
  }
  if (!best || best.d > 15) return undefined;
  if (best.d <= IN_TOWN_UNITS) return { name: best.name, distance: best.d, text: best.name };
  const dir = `${Math.abs(best.dn) > best.d * 0.38 ? (best.dn > 0 ? 'N' : 'S') : ''}${Math.abs(best.de) > best.d * 0.38 ? (best.de > 0 ? 'E' : 'W') : ''}`;
  return { name: best.name, distance: best.d, text: `${Math.round(best.d)} ${dir} of ${best.name}` };
}

/**
 * A town named in a place's name as a player says it: "Holtburg lifestone", "the lifestone in Holtburg", "Holtburg's
 * Life Stone". The town (its note's name) and the rest of the words; null when no town's name is in it as whole words,
 * or nothing else is left.
 */
export function townInName(query: string, towns: readonly AgentTown[] = activeTowns): { town: string; rest: string } | null {
  const q = query.trim();
  let best: { town: string; rest: string } | null = null;
  for (const t of towns) {
    const esc = t.name.replace(/[.*+?^${}()|[\]\\]/g, '\\$&');
    const m = new RegExp(`(^|\\s)${esc}(?:'s)?(?=\\s|$)`, 'i').exec(q);
    if (!m) continue;
    const rest = (q.slice(0, m.index) + ' ' + q.slice(m.index + m[0].length))
      .replace(/\b(in|at|of|near|by)\s*$/i, '').replace(/^\s*(the)\b/i, '').replace(/\s+/g, ' ').trim();
    if (!rest || (best && best.town.length >= t.name.length)) continue;
    best = { town: t.name, rest };
  }
  return best;
}
